<script>
import {data,profile,updateData,notify,download} from '../store.js';import {WHAT_IF_PROGRAMS,whatIf} from '../academics.js';import {courseLabel} from '../catalog.js';import {saveScenario,savedScenario} from '../workspace-directory.js';import Icon from './Icon.svelte';
let selectedProgram=$state('data');let scenario=$state(null);let activeReport=$state('');
function run(){const program=WHAT_IF_PROGRAMS.find(p=>p.id===selectedProgram);scenario={program,...whatIf($profile,program)};activeReport='';}
function save(){const next=saveScenario($data.workspace,scenario.program.id);if(!next)return;updateData({...$data,workspace:next});activeReport=next.whatIfReports[0].id;notify('what-if report saved for this student.');}
function open(report){scenario=savedScenario($profile,report);selectedProgram=report.programId;activeReport=report.id;}
function remove(id){updateData({...$data,workspace:{...$data.workspace,whatIfReports:$data.workspace.whatIfReports.filter(r=>r.id!==id)}});if(activeReport===id)activeReport='';notify('Saved scenario removed.');}
function exportReport(){download('what-if-report.txt',`WHAT-IF REPORT\n${$profile.name}\n${scenario.program.name}\n\nMatches\n${scenario.matches.map(courseLabel).join('\n')||'None'}\n\nStill needed in this scenario\n${scenario.missing.map(courseLabel).join('\n')||'None'}\n\nNo major, transcript, or enrollment has changed.\n`);}
</script>
<section class="panel padded academic-copy"><h2>What-if Report Selection</h2><p>Compare program requirements against completed coursework. Create a report, then save it to revisit from either My Admissions or Academic Progress.</p><div class="academic-controls"><label>Program scenario<select bind:value={selectedProgram}>{#each WHAT_IF_PROGRAMS as p}<option value={p.id}>{p.name}</option>{/each}</select></label><button class="button primary" onclick={run}>Create New Report<Icon name="arrow" size={16}/></button></div><p class="fine-print">This does not change your current major, certificate, transcript, enrollment, or graduation application.</p></section>
{#if scenario}<section class="panel padded spaced" aria-live="polite"><div class="section-heading"><h2>{scenario.program.name}</h2><span class="badge neutral">scenario</span></div><div class="progress-track big"><span style:width={`${scenario.percent}%`}></span></div><p class="muted spaced">{scenario.matches.length} of {scenario.program.codes.length} requirements match completed coursework.</p><div class="scenario-columns"><div><h3>Matching coursework</h3><ul class="academic-list">{#each scenario.matches as code}<li>{courseLabel(code)}</li>{:else}<li>No matching courses yet.</li>{/each}</ul></div><div><h3>Still needed in this scenario</h3><ul class="academic-list">{#each scenario.missing as code}<li>{courseLabel(code)}</li>{:else}<li>All listed requirements match.</li>{/each}</ul></div></div><p class="fine-print">Saved scenarios use the selected student’s transcript. Review program and equivalency requirements with your advisor.</p><div class="button-row spaced"><button class="button primary" disabled={!!activeReport} onclick={save}>{activeReport?'Report saved':'Save this report'}<Icon name="check" size={15}/></button><button class="button secondary" onclick={exportReport}>Download report<Icon name="download" size={15}/></button><a class="button secondary" href="#/academics/bearcat-network">Discuss with advising<Icon name="arrow" size={15}/></a></div></section>{/if}
<section class="panel padded spaced"><h2>View a Saved What-if Report</h2>{#if $data.workspace.whatIfReports.length}<div class="account-records spaced">{#each $data.workspace.whatIfReports as report}{@const program=WHAT_IF_PROGRAMS.find(p=>p.id===report.programId)}<article class="account-record"><div><strong>{program.name}</strong><small>Requested on {new Date(report.createdAt).toLocaleString()}</small><span class="badge neutral">Saved report</span></div><div class="button-row"><button class="button secondary" aria-label={`Open saved ${program.name} report`} onclick={()=>open(report)}>Open report</button><button class="button quiet" aria-label={`Remove saved ${program.name} report`} onclick={()=>remove(report.id)}>Remove</button></div></article>{/each}</div>{:else}<p class="muted small spaced">No saved reports yet. Create a new report and save it here.</p>{/if}</section>
